// Netlify Edge Functions (Deno).  The module's bytes are embedded (wasm-bytes.js, generated by the packager): an edge function cannot read files next to it.  Any request may reach any
// instance, so the state is in Redis (Upstash; docs/deploy.md, Shared state) and every request commits against the version it read.  Without a store the answer is 503.
import bytes from "../../wasm-bytes.js";
import { sharedApp } from "../../runtime/shared.js";
import { assets } from "../../runtime/assets.js";

const app = sharedApp({ module: bytes, hostName: "netlify-edge", env: (name) => Deno.env.get(name), assets });
export default (request, context) => {
  const response = app.fetch(request);
  context?.waitUntil?.(response.then(() => app.settled(), () => {}));
  return response;
};
// everything but the function variant
export const config = { path: "/*", excludedPath: ["/fn", "/fn/*"] };
